// El aviso de Stripe NO se cree: se relee el pago en Stripe y se comprueba que sea real.
const prueba = $('datos_prueba').isExecuted ? $('datos_prueba').first().json : null;
const pedido = prueba || $('id_desde_stripe').first().json;
const pi = $input.first().json;
if (!pi || !pi.id) throw new Error('Stripe no devolvio el pago (respuesta vacia).');
if (pi.object !== 'payment_intent' || pi.id !== pedido.pago_id) throw new Error('Stripe devolvio otra cosa en vez del pago ' + pedido.pago_id + '. No se proceso.');
if (pi.status !== 'succeeded') throw new Error('El pago ' + pi.id + ' NO esta cobrado en Stripe (estado: ' + pi.status + '). No se proceso: posible aviso falso.');
if (pi.livemode !== true) throw new Error('El pago ' + pi.id + ' es del modo de prueba de Stripe, no es una venta real. No se proceso.');
const dias = (Date.now() / 1000 - pi.created) / 86400;
if (!prueba && dias > 3) throw new Error('El pago ' + pi.id + ' es de hace ' + Math.floor(dias) + ' dias (Stripe solo reenvia avisos hasta 3 dias). Posible aviso repetido o falso: no se proceso, revisarlo a mano.');
const referencia = String((pi.payment_details && pi.payment_details.order_reference) || '');
return [{ json: { ...pi, referencia, es_factura: /^in_[A-Za-z0-9]+$/.test(referencia) } }];

// Todo determinista: quien es, que compro, si es alta o cuota mensual.
const ZONA = 'America/Montevideo';
const prueba = $('datos_prueba').isExecuted ? $('datos_prueba').first().json : null;
const pi = $('validar_pago').first().json;
const factura = $('leer_factura').isExecuted ? $('leer_factura').first().json : null;
const sesiones = $('leer_checkout').isExecuted ? ($('leer_checkout').first().json.data || []) : [];
const ses = sesiones[0] || null;
const cus = (pi.customer && typeof pi.customer === 'object') ? pi.customer : {};
const cargo = (pi.latest_charge && typeof pi.latest_charge === 'object') ? pi.latest_charge : {};
const bd = cargo.billing_details || {};
const cd = (ses && ses.customer_details) || {};
// Lo que escribe la compradora se limpia: sin < > " ni caracteres raros, y sin = + - @ al principio (asi no se vuelve formula en Sheets)
const limpiar = s => String(s || '').replace(/[<>"\u0000-\u001f]/g, '').replace(/^[=+\-@\s]+/, '').trim().slice(0, 150);
let name = limpiar(cus.name || (factura && factura.customer_name) || cd.name || bd.name);
let email = String(cus.email || (factura && factura.customer_email) || cd.email || bd.email || pi.receipt_email || '').trim().toLowerCase();
let producto = String(pi.description || '').trim();
if (!producto && factura) producto = ((factura.lines && factura.lines.data) || []).map(l => l.description).filter(Boolean).join(' + ');
if (!producto && ses) producto = ((ses.line_items && ses.line_items.data) || []).map(l => l.description).filter(Boolean).join(' + ');
producto = limpiar(producto);
// Cobro mensual de una suscripcion (no es la compra): solo va a finanzas
const es_renovacion = !!(factura && factura.billing_reason === 'subscription_cycle');
const tipo = es_renovacion ? 'cuota_mensual' : (factura ? String(factura.billing_reason || 'factura') : (ses ? 'link_de_pago' : 'otro'));
if (prueba) {
  email = String(prueba.email_prueba || '').trim().toLowerCase();
  name = 'PRUEBA ' + (name || 'sin nombre');
  if (prueba.curso_prueba) producto = limpiar(prueba.curso_prueba);
}
const email_ok = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) && email.length <= 254;
if (!name) name = email_ok ? email : 'sin nombre';
const curso = producto.toLowerCase();
// Sin tildes: 'Método Imán' y 'metodo iman' son lo mismo
let curso_clave = curso.normalize('NFD').replace(/[̀-ͯ]/g, '');
let motivo_alerta = curso_clave ? 'No coincide con ningún curso (artista, imán, marcas, podcashter).' : 'El pago no trae nombre de producto.';
if (!email_ok) { curso_clave = ''; motivo_alerta = 'El pago no trae un email válido de la compradora.'; }
const fecha = DateTime.fromSeconds(pi.created).setZone(ZONA).toFormat('yyyy-MM-dd');
const precio = String(pi.amount / 100);
const moneda = String(pi.currency || '').toUpperCase();
const pago_id = prueba ? pi.id + '-prueba-' + (curso_clave || 'sin-curso') : pi.id;
return [{ json: { pago_id, email: email_ok ? email : '', name, producto, curso, curso_clave, fecha, precio, moneda, es_renovacion, tipo, motivo_alerta, es_prueba: !!prueba } }];
